import React, { useState } from 'react';
import { Button, Form, Input, Radio, message } from 'antd';
import '../../assets/style/MyCollapse/RadioBox.scss'
import { postSpaceRadio } from '../../utils/request.js';

const RadioBox = () => {

    const [form] = Form.useForm();

    const [radio_type, set_radio_type] = useState('space_radio');
    const [radio_send_btn_loading, set_radio_send_btn_loading] = useState(false);

    const on_form_Change = ({ radio_type }) => {
        if (radio_type)
            set_radio_type(radio_type);
    };

    const on_form_finish = (form_data) => {
        // console.log(form_data);
        if (form_data.SpaceId)
            send_radio_handle(form_data.SpaceId, form_data.msg);
    };

    const send_radio_handle = (spaceId, msg) => {
        set_radio_send_btn_loading(true)
        let sendData = new FormData();
        sendData.append('msg', msg);
        postSpaceRadio(spaceId, sendData).then(res => {
            console.log(res);
            message.destroy();
            message.success('广播发送成功')
            set_radio_send_btn_loading(false)
        })
    }

    return (
        <>
            <div id="radio_send_div">
                <div id="form_div">
                    <Form
                        layout={'vertical'}
                        form={form}
                        initialValues={{
                            radio_type: 'space_radio'
                        }}
                        onValuesChange={on_form_Change}
                        onFinish={on_form_finish}
                    >
                        <Form.Item label="广播类别" name="radio_type">
                            <Radio.Group value={radio_type}>
                                <Radio.Button value="world_radio">世界广播</Radio.Button>
                                <Radio.Button value="space_radio">空间广播</Radio.Button>
                                <Radio.Button value="group_radio">群组广播</Radio.Button>
                            </Radio.Group>
                        </Form.Item>
                        {
                            radio_type === 'space_radio' ?
                                <Form.Item label="SpaceId" name="SpaceId">
                                    <Input placeholder="空间SpaceId" />
                                </Form.Item>
                                : ''
                        }
                        <Form.Item label="广播内容" name="msg">
                            <Input placeholder="请输入要发送的广播内容" />
                        </Form.Item>
                        <Form.Item >
                            <Button type="primary" htmlType="submit" loading={radio_send_btn_loading}>发送</Button>
                        </Form.Item>
                    </Form>
                </div>
            </div>
        </>
    );
}

export default RadioBox;
