import axios from 'axios';

const baseURL = 'http://chatspace.iceclean.top/space'
// const baseURL = 'http://localhost:19010/space'

// 获取list聊天列表
export function postSpaceRadio(spaceId, sendData) {
    return new Promise((resolve, reject) => {
        axios.post(baseURL + '/space/admin/cast/space/' + spaceId, sendData, { headers: { 'admin-tag': 1 } })
            .then(res => {
                if (res.data.msg === '未知异常') {
                    // message.error('请重新登录！')
                } else {
                    resolve(res.data.data);
                }
            }).catch(error => {
                reject(error);
            })
    })
}